using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;using LWS.TruckBowling;
namespace LWS.TruckMinefield.Editor {
public static class MinefieldAuthoring {
 public const string Folder="TruckMinefield",Scene="Assets/TruckMinefield/Scenes/TruckMinefield.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<MinefieldMatch>(Folder);m.setup.count=8;m.feedback.clips=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckKeepaway/Prefabs/ComicBlast.prefab")!=null?LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create():null;
 m.feedback.clips[2]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Weather/WeatherMakerThunderIntense1.mp3");
 var data=AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/TruckMinefield/Materials/Mile terrain.asset");if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,"Assets/TruckMinefield/Materials/Mile terrain.asset");}data.heightmapResolution=513;data.size=new Vector3(114,18,1680);var heights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++){float pz=z/512f*1680-12,px=x/512f*114-57;float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,60,pz));heights[z,x]=blend*(.7f+Mathf.PerlinNoise(px*.045f+15,pz*.018f+4)*3+Mathf.Sin(pz*.023f+px*.012f)*.6f)/18;}data.SetHeights(0,0,heights);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer")};data.alphamapResolution=256;var alpha=new float[256,256,2];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float noise=Mathf.PerlinNoise(x*.08f,z*.035f);alpha[z,x,1]=Mathf.Clamp01((noise-.35f)*2);alpha[z,x,0]=1-alpha[z,x,1];}data.SetAlphamaps(0,0,alpha);m.terrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();m.terrain.name="One mile rolling meadow and mud";m.terrain.transform.position=new Vector3(-57,0,-12);m.terrain.heightmapPixelError=4;m.terrain.drawInstanced=true;var terrainMat=SportsEventAuthoring.Mat(Folder,"Mile terrain",Color.white);terrainMat.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");m.terrain.materialTemplate=terrainMat;
 m.racers=new MinefieldRacer[8];m.identities=new TextMesh[8];for(int i=0;i<8;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Minefield competitor "+(i+1),new Vector3((i-3.5f)*8,.55f,0),i);t.maxSpeed=26;t.motorTorque=10;t.steerAngle=38;t.body.maxLinearVelocity=95;t.body.maxAngularVelocity=12;SportsRallyAuthoring.FitTruck(t);var r=t.gameObject.AddComponent<MinefieldRacer>();r.match=m;r.truck=t;r.slot=i;m.racers[i]=r;m.identities[i]=SportsEventAuthoring.Label("Minefield player "+i,m.setup.players[i].name,t.transform.position+Vector3.up*3,.16f,m.setup.players[i].color);m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();}
 m.views=SportsRallyAuthoring.Views(m,m.racers.Select(x=>x.truck).ToArray());m.views.broadcast.view.farClipPlane=2200;m.weatherField=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=m.weatherField;m.replay=SportsRallyAuthoring.Replay(m,m.racers.Select(x=>x.truck.visuals).ToArray());m.replay.capacity=3700;
 var field=new GameObject("Seeded readable minefield and sheep").transform;var list=new System.Collections.Generic.List<MinefieldHazard>();var random=new System.Random(m.seed);var mine=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckMinefield/Art/Imported/Props_Landmine_Lvl1.prefab");if(mine==null)throw new Exception("Imported actual landmine required");for(int row=0;row<77;row++)for(int col=0;col<7;col++){float z=43+row*20+(float)random.NextDouble()*8,x=(col-3)*12+(float)(random.NextDouble()-.5)*8;float safer=Mathf.Sin(z*.014f)*24;if(Mathf.Abs(x-safer)<4)continue;var root=new GameObject("Subtle mine plate "+row+"-"+col);root.transform.SetParent(field,false);root.transform.position=m.Surface(new Vector3(x,0,z));var h=root.AddComponent<MinefieldHazard>();h.match=m;h.StartPosition=root.transform.position;var shape=root.AddComponent<SphereCollider>();shape.isTrigger=true;shape.radius=1.35f;shape.center=Vector3.up*.3f;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(root.transform,"Assets/TruckMinefield/Art/Imported/Props_Landmine_Lvl1.prefab",new Vector3(1.5f,.38f,1.5f),0);list.Add(h);}
 var sheep=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckCheeseRolling/Prefabs/ExplosiveSheep.prefab");for(int i=0;i<20;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(sheep);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var prior=g.GetComponent<LWS.TruckCheeseRolling.CheeseSheep>();if(prior.warning!=null)prior.warning.SetActive(false);UnityEngine.Object.DestroyImmediate(prior);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);g.transform.SetParent(field,false);g.transform.position=m.Surface(new Vector3((float)(random.NextDouble()-.5)*82,0,70+i*69))+Vector3.up*.55f;var h=g.AddComponent<MinefieldHazard>();h.match=m;h.kind=1;h.StartPosition=g.transform.position;var shape=g.AddComponent<SphereCollider>();shape.isTrigger=true;shape.radius=1.3f;list.Add(h);}m.hazards=list.ToArray();
 m.blasts=new ParticleSystem[8];var flare=SportsChaosAuthoring.Flare(Folder);for(int i=0;i<8;i++){var fx=new GameObject("Pooled Minefield launch "+i).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(fx,flare);var main=fx.main;main.startSize=new ParticleSystem.MinMaxCurve(3,7);m.blasts[i]=fx;}
 m.blastFlags=new MinefieldFlag[8];m.landingFlags=new MinefieldFlag[8];m.bestFlags=new MinefieldFlag[8];for(int i=0;i<8;i++){m.blastFlags[i]=Flag(m,"Blast marker "+i);m.landingFlags[i]=Flag(m,"Landing marker "+i);m.bestFlags[i]=Flag(m,"Personal best marker "+i);}
 Dress(m);MinefieldLandscapeAuthoring.Install(m);MinefieldEffectsAuthoring.Install(m);m.replay.capacity=6000;m.replay.maximumReplayAge=120;SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);MinefieldGoddessAuthoring.Install(m);SportsEventAuthoring.Save(Folder);Validate();}
 static MinefieldFlag Flag(MinefieldMatch m,string name){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckMinefield/Art/Imported/flag.fbx");if(source==null)throw new Exception("Actual imported flag model required");var root=new GameObject(name);var art=UnityEngine.Object.Instantiate(source,root.transform,false);var all=art.GetComponentsInChildren<Renderer>(true);var b=all[0].bounds;foreach(var r in all)b.Encapsulate(r.bounds);float scale=8/Mathf.Max(.1f,b.size.y);art.transform.localScale*=scale;art.transform.localPosition=-new Vector3(b.center.x,b.min.y,b.center.z)*scale;var f=root.AddComponent<MinefieldFlag>();f.weather=m.weatherField;f.bones=art.GetComponentsInChildren<Transform>(true).Where(x=>x.name.StartsWith("Skeleton_Joint")).ToArray();f.cloth=all.FirstOrDefault(r=>r is SkinnedMeshRenderer)??all[0];var steel=SportsEventAuthoring.Mat(Folder,"Brushed flagpole",new Color(.20f,.23f,.25f),.65f);var cloth=SportsEventAuthoring.Mat(Folder,"Colored woven flag",Color.white,.12f);cloth.SetFloat("_Cull",0);foreach(var r in all)r.sharedMaterial=r==f.cloth?cloth:steel;f.caption=SportsEventAuthoring.Label(name+" label","",new Vector3(0,10.2f,0),.24f,Color.white);f.caption.transform.SetParent(root.transform,false);f.caption.gameObject.AddComponent<SportsPerCameraBillboard>().distanceSizing=true;f.shadow=SportsEventAuthoring.Label(name+" caption shadow","",Vector3.zero,.24f,Color.black);f.shadow.transform.SetParent(f.caption.transform,false);f.shadow.transform.localPosition=new Vector3(.025f,-.025f,.02f);foreach(var collider in root.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.012f,all),new LOD(.0015f,all.Where(r=>r!=f.cloth).ToArray())});lod.RecalculateBounds();root.SetActive(false);return f;}
 static void Dress(MinefieldMatch m){var root=new GameObject("Mile course authored dressing").transform;var contact=SportsEventAuthoring.Contact(Folder,"Course props contact",.3f,.1f);for(int i=0;i<86;i++){float z=i*19;float x=(i%2==0?-1:1)*(49+i%3*2);var p=m.Surface(new Vector3(x,0,z));LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,p,i%4==0?3:8+i%5,i%4!=0,Folder);if(i%8==0){var marker=SportsEventAuthoring.Label("Mile progress marker",SportsMeasure.Feet(z),p+Vector3.up*3,.35f,Color.white);marker.gameObject.AddComponent<SportsPerCameraBillboard>();}}
 var ramp=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckTerrierRacing/Prefabs/Timber launch ramp.prefab");for(int i=0;i<12;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(ramp);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);foreach(var c in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(c);g.transform.SetParent(root,false);g.transform.position=m.Surface(new Vector3(i%2==0?-24:24,0,90+i*110));g.name="Optional textured timber jump";}
 for(int i=0;i<32;i++){var p=m.Surface(new Vector3(i%2==0?-44:44,0,55+i*48));string path=i%3==0?"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab":i%3==1?"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab":"Assets/IndieKit/Crates and Barrels/Prefabs/Non-Destructible/crate_01.prefab";var prop=new GameObject("Installed physical side prop");prop.transform.SetParent(root,false);prop.transform.position=p;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(prop.transform,path,new Vector3(2,2,2),0);var shape=prop.AddComponent<BoxCollider>();shape.size=new Vector3(1.6f,1.6f,1.6f);shape.center=Vector3.up*.8f;shape.sharedMaterial=contact;}
 var green=SportsEventAuthoring.Mat(Folder,"Finish emerald",new Color(.02f,.65f,.35f));for(int side=-1;side<=1;side+=2){var p=m.Surface(new Vector3(side*55,0,MinefieldRules.Mile));SportsEventAuthoring.Box("Mile finish tower",p+Vector3.up*7,new Vector3(1.5f,14,1.5f),green,contact,root);}var finish=SportsEventAuthoring.Label("One mile instant victory sign","ONE MILE · DRIVE THROUGH TO WIN",m.Surface(new Vector3(0,0,MinefieldRules.Mile))+Vector3.up*14,.8f,Color.white);finish.gameObject.AddComponent<SportsPerCameraBillboard>();}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<MinefieldMatch>();if(m==null||m.racers.Length!=8||m.hazards.Length<400||m.blastFlags.Length!=8||m.views.views.Length!=4||m.replay.ghosts.Length!=8||m.terrain==null||m.grounds==null||m.grounds.Length!=4||m.feedback.clips.Any(c=>c==null))throw new Exception("Minefield saved references incomplete");foreach(var g in m.replay.ghosts)if(g.GetComponentsInChildren<Collider>(true).Length>0||g.GetComponentsInChildren<Rigidbody>(true).Length>0)throw new Exception("Minefield replay must be nonphysical");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One Minefield listener required");Debug.Log("MINEFIELD_SAVED_VALIDATED");}
